15	import { revertFileChanges } from '../utils/rewindFileOps.js';
16	import { RewindOutcome } from '../components/RewindConfirmation.js';
17	import type { Content } from '@google/genai';
18	import {
19	  checkExhaustive,
20	  coreEvents,
21	  debugLogger,
22	  logRewind,
23	  RewindEvent,
24	  type ChatRecordingService,
25	  type GeminiClient,
26	  convertSessionToClientHistory,
27	} from '@google/gemini-cli-core';
