29	/**
30	 * Helper function to handle the core logic of rewinding a conversation.
31	 * This function encapsulates the steps needed to rewind the conversation,
32	 * update the client and UI history, and clear the component.
33	 *
34	 * @param context The command context.
35	 * @param client Gemini client
36	 * @param recordingService The chat recording service.
37	 * @param messageId The ID of the message to rewind to.
38	 * @param newText The new text for the input field after rewinding.
39	 */
40	async function rewindConversation(
41	  context: CommandContext,
42	  client: GeminiClient,
43	  recordingService: ChatRecordingService,
44	  messageId: string,
45	  newText: string,
46	) {
47	  try {
48	    const conversation = recordingService.rewindTo(messageId);
49	    if (!conversation) {
50	      const errorMsg = 'Could not fetch conversation file';
51	      debugLogger.error(errorMsg);
52	      context.ui.removeComponent();
53	      coreEvents.emitFeedback('error', errorMsg);
54	      return;
55	    }
56	
57	    // Convert to UI and Client formats
58	    const { uiHistory } = convertSessionToHistoryFormats(conversation.messages);
59	    const clientHistory = convertSessionToClientHistory(conversation.messages);
60	
61	    client.setHistory(clientHistory as Content[]);
62	
63	    // Reset context manager as we are rewinding history
64	    await context.services.config?.getContextManager()?.refresh();
65	
66	    // Update UI History
67	    // We generate IDs based on index for the rewind history
68	    const startId = 1;
69	    const historyWithIds = uiHistory.map(
70	      (item, idx) =>
71	        ({
72	          ...item,
73	          id: startId + idx,
74	        }) as HistoryItem,
75	    );
76	
77	    // 1. Remove component FIRST to avoid flicker and clear the stage
78	    context.ui.removeComponent();
79	
80	    // 2. Load the rewound history and set the input
81	    context.ui.loadHistory(historyWithIds, newText);
82	  } catch (error) {
83	    // If an error occurs, we still want to remove the component if possible
84	    context.ui.removeComponent();
85	    coreEvents.emitFeedback(
86	      'error',
87	      error instanceof Error ? error.message : 'Unknown error during rewind',
88	    );
89	  }
90	}
91	
92	export const rewindCommand: SlashCommand = {
93	  name: 'rewind',
94	  description: 'Jump back to a specific message and restart the conversation',
95	  kind: CommandKind.BUILT_IN,
96	  action: (context) => {
97	    const config = context.services.config;
98	    if (!config)
99	      return {
100	        type: 'message',
101	        messageType: 'error',
102	        content: 'Config not found',
103	      };
104	
105	    const client = config.getGeminiClient();
106	    if (!client)
107	      return {
108	        type: 'message',
109	        messageType: 'error',
110	        content: 'Client not initialized',
111	      };
112	
113	    const recordingService = client.getChatRecordingService();
114	    if (!recordingService)
115	      return {
116	        type: 'message',
117	        messageType: 'error',
118	        content: 'Recording service unavailable',
119	      };
120	
121	    const conversation = recordingService.getConversation();
122	    if (!conversation)
123	      return {
124	        type: 'message',
125	        messageType: 'info',
126	        content: 'No conversation found.',
127	      };
128	
129	    const hasUserInteractions = conversation.messages.some(
130	      (msg) => msg.type === 'user',
131	    );
132	    if (!hasUserInteractions) {
133	      return {
134	        type: 'message',
135	        messageType: 'info',
136	        content: 'Nothing to rewind to.',
137	      };
138	    }
139	
140	    return {
141	      type: 'custom_dialog',
142	      component: (
143	        <RewindViewer
144	          conversation={conversation}
145	          onExit={() => {
146	            context.ui.removeComponent();
147	          }}
148	          onRewind={async (messageId, newText, outcome) => {
149	            if (outcome !== RewindOutcome.Cancel) {
150	              logRewind(config, new RewindEvent(outcome));
151	            }
152	            switch (outcome) {
153	              case RewindOutcome.Cancel:
154	                context.ui.removeComponent();
155	                return;
156	
157	              case RewindOutcome.RevertOnly:
158	                if (conversation) {
159	                  await revertFileChanges(conversation, messageId);
160	                }
161	                context.ui.removeComponent();
162	                coreEvents.emitFeedback('info', 'File changes reverted.');
163	                return;
164	
165	              case RewindOutcome.RewindAndRevert:
166	                if (conversation) {
167	                  await revertFileChanges(conversation, messageId);
168	                }
169	                await rewindConversation(
170	                  context,
171	                  client,
172	                  recordingService,
173	                  messageId,
174	                  newText,
175	                );
176	                return;
177	
178	              case RewindOutcome.RewindOnly:
179	                await rewindConversation(
180	                  context,
181	                  client,
182	                  recordingService,
183	                  messageId,
184	                  newText,
185	                );
186	                return;
187	
188	              default:
189	                checkExhaustive(outcome);
190	            }
191	          }}
192	        />
193	      ),
194	    };
195	  },
196	};
