88	                    <Box>
89	                      <Text>
90	                        <Text color={theme.text.accent}>{hookName}</Text>
91	                        <Text color={statusColor}>{` [${statusText}]`}</Text>
92	                      </Text>
93	                    </Box>
94	                    <Box paddingLeft={2} flexDirection="column">
95	                      {hook.config.description && (
96	                        <Text italic>{hook.config.description}</Text>
97	                      )}
98	                      <Text dimColor>
