100	                        {hook.config.name &&
101	                          hook.config.command &&
102	                          ` | Command: ${hook.config.command}`}
103	                        {hook.matcher && ` | Matcher: ${hook.matcher}`}
104	                        {hook.sequential && ` | Sequential`}
105	                        {hook.config.timeout &&
106	                          ` | Timeout: ${hook.config.timeout}s`}
107	                      </Text>
108	                    </Box>
109	                  </Box>
110	                );
111	              })}
112	            </Box>
113	          </Box>
114	        ))}
115	      </Box>
116	      <Box marginTop={1}>
117	        <Text dimColor>
118	          Tip: Use <Text bold>/hooks enable {'<hook-name>'}</Text> or{' '}
119	          <Text bold>/hooks disable {'<hook-name>'}</Text> to toggle individual
120	          hooks. Use <Text bold>/hooks enable-all</Text> or{' '}
121	          <Text bold>/hooks disable-all</Text> to toggle all hooks at once.
122	        </Text>
123	      </Box>
124	    </Box>
125	  );
126	};
