import type React from 'react';
import { useCallback, useMemo, useState } from 'react';
import { Box, Text } from 'ink';
import { theme } from '../semantic-colors.js';
import { useKeypress } from '../hooks/useKeypress.js';

/**
 * A single hook entry displayed in the {@link HooksDialog}.
 */
export interface HookEntry {
  config: {
    name?: string;
    command?: string;
    type?: string;
    description?: string;
    timeout?: number;
  };
  source: string;
  eventName: string;
  enabled: boolean;
  matcher?: string;
  sequential?: boolean;
}

interface HooksDialogProps {
  hooks: HookEntry[];
  onClose: () => void;
  maxVisibleHooks?: number;
}

/**
 * Get the display name for a hook, falling back to the command when no
 * friendly name is configured.
 */
function getHookDisplayName(hook: HookEntry): string {
  return hook.config.name || hook.config.command || 'unknown';
}

/**
 * An interactive dialog that displays the configured hooks grouped by event
 * name. It is rendered separately from the message stream and can be dismissed
 * with the Escape key. When more hooks are configured than `maxVisibleHooks`,
 * the list can be scrolled with the up/down arrow keys.
 */
export const HooksDialog: React.FC<HooksDialogProps> = ({
  hooks,
  onClose,
  maxVisibleHooks,
}) => {
  const [scrollOffset, setScrollOffset] = useState(0);

  // The effective number of hooks to show at once. When not provided (or not
  // positive) all hooks are shown and scrolling is disabled.
  const visibleCount =
    maxVisibleHooks && maxVisibleHooks > 0 ? maxVisibleHooks : hooks.length;

  const maxScrollOffset = Math.max(0, hooks.length - visibleCount);
  const clampedOffset = Math.min(scrollOffset, maxScrollOffset);

  const canScroll = hooks.length > visibleCount;
  const showUpIndicator = canScroll && clampedOffset > 0;
  const showDownIndicator = canScroll && clampedOffset < maxScrollOffset;

  useKeypress(
    useCallback(
      (key) => {
        if (key.name === 'escape') {
          onClose();
          return;
        }

        if (!canScroll) {
          return;
        }

        if (key.name === 'up') {
          setScrollOffset((prev) => Math.max(0, prev - 1));
        } else if (key.name === 'down') {
          setScrollOffset((prev) => Math.min(maxScrollOffset, prev + 1));
        }
      },
      [onClose, canScroll, maxScrollOffset],
    ),
    { isActive: true },
  );

  // Compute the visible slice of hooks, then group that slice by event name for
  // rendering. Hooks are kept in their original order so scrolling behaves
  // predictably across group boundaries.
  const visibleGroups = useMemo(() => {
    const visibleHooks = hooks.slice(
      clampedOffset,
      clampedOffset + visibleCount,
    );

    const groups: Array<{ eventName: string; hooks: HookEntry[] }> = [];
    for (const hook of visibleHooks) {
      let group = groups[groups.length - 1];
      if (!group || group.eventName !== hook.eventName) {
        group = { eventName: hook.eventName, hooks: [] };
        groups.push(group);
      }
      group.hooks.push(hook);
    }
    return groups;
  }, [hooks, clampedOffset, visibleCount]);

  return (
    <Box
      flexDirection="column"
      borderStyle="round"
      borderColor={theme.status.warning}
      paddingX={1}
    >
      <Box flexDirection="column">
        <Text color={theme.status.warning} bold underline>
          ⚠️ Security Warning:
        </Text>
        <Text color={theme.status.warning}>
          Hooks can execute arbitrary commands on your system. Only use hooks
          from sources you trust. Review hook scripts carefully.
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text>
          Learn more:{' '}
          <Text color={theme.text.link}>https://geminicli.com/docs/hooks</Text>
        </Text>
      </Box>

      <Box marginTop={1}>
        <Text bold>Configured Hooks:</Text>
      </Box>

      {hooks.length === 0 ? (
        <Box paddingLeft={2} marginTop={1}>
          <Text>No hooks configured.</Text>
        </Box>
      ) : (
        <Box flexDirection="column" paddingLeft={2} marginTop={1}>
          {showUpIndicator && <Text color={theme.text.primary}>▲</Text>}

          {visibleGroups.map((group) => (
            <Box
              key={group.eventName}
              flexDirection="column"
              marginBottom={1}
            >
              <Text color={theme.text.accent} bold>
                {group.eventName}:
              </Text>
              <Box flexDirection="column" paddingLeft={2}>
                {group.hooks.map((hook, index) => {
                  const hookName = getHookDisplayName(hook);
                  const statusColor = hook.enabled
                    ? theme.status.success
                    : theme.text.secondary;
                  const statusText = hook.enabled ? 'enabled' : 'disabled';

                  return (
                    <Box
                      key={`${group.eventName}-${index}`}
                      flexDirection="column"
                    >
                      <Box>
                        <Text>
                          <Text color={theme.text.accent}>{hookName}</Text>
                          <Text color={statusColor}>
                            {` [${statusText}]`}
                          </Text>
                        </Text>
                      </Box>
                      <Box paddingLeft={2} flexDirection="column">
                        {hook.config.description && (
                          <Text italic>{hook.config.description}</Text>
                        )}
                        <Text dimColor>
                          Source: {hook.source}
                          {hook.config.name &&
                            hook.config.command &&
                            ` | Command: ${hook.config.command}`}
                          {hook.matcher && ` | Matcher: ${hook.matcher}`}
                          {hook.sequential && ` | Sequential`}
                          {hook.config.timeout &&
                            ` | Timeout: ${hook.config.timeout}s`}
                        </Text>
                      </Box>

